#!/usr/bin/env python3
"""Generate the Home Assistant copy of the changelog from the root CHANGELOG.md.

Usage:
    render_ha_changelog.py CHANGELOG.md remoteterm/CHANGELOG.md          # write
    render_ha_changelog.py CHANGELOG.md remoteterm/CHANGELOG.md --check  # verify

Why a separate copy: the Supervisor reads CHANGELOG.md from the app's own
folder, and Home Assistant's update dialog only trims it to the versions being
installed when each version heading is exactly the bare version ("## 3.26.8").
With a heading like "## [3.26.8] - 2026-11-12" the dialog shows the whole file.

The root changelog keeps "## [X.Y.Z] - DATE" headings and link references. The
generated copy has:
- no [Unreleased] section and no link reference definitions;
- "## X.Y.Z" headings, with the date on the next line;
- each section's body unchanged.
"""

import argparse
import re
import sys
from pathlib import Path

HEADER = (
    "# Changelog\n\n"
    "<!-- Generated from the repository's root CHANGELOG.md by "
    ".github/scripts/render_ha_changelog.py. Do not edit this file. -->\n"
)
HEADING = re.compile(r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\S+))?\s*$")
LINK_REF = re.compile(r"^\[[^\]]+\]: ")


def render(source: str) -> str:
    sections: list[str] = []
    current: list[str] | None = None

    for line in source.splitlines():
        if LINK_REF.match(line):
            break  # link reference definitions end the file
        heading = HEADING.match(line)
        if heading:
            if current is not None:
                sections.append("\n".join(current).strip())
            if heading["version"].lower() == "unreleased":
                current = None
                continue
            current = [f"## {heading['version']}", ""]
            if heading["date"]:
                current += [f"_Released {heading['date']}_", ""]
        elif line.startswith("## "):
            sys.exit(f"Unrecognised version heading: {line!r} (expected '## [X.Y.Z] - YYYY-MM-DD')")
        elif current is not None:
            current.append(line)

    if current is not None:
        sections.append("\n".join(current).strip())
    if not sections:
        sys.exit("No released versions found in the changelog")
    sections = [re.sub(r"\n{3,}", "\n\n", s) for s in sections]
    return HEADER + "\n" + "\n\n".join(sections) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("source", help="root CHANGELOG.md")
    parser.add_argument("output", help="the app's CHANGELOG.md read by Home Assistant")
    parser.add_argument("--check", action="store_true", help="fail if output is not up to date")
    args = parser.parse_args()

    rendered = render(Path(args.source).read_text())
    output = Path(args.output)
    if args.check:
        current = output.read_text() if output.exists() else ""
        if current != rendered:
            sys.exit(
                f"{args.output} is out of date with {args.source}. Run:\n"
                f"  python3 .github/scripts/render_ha_changelog.py {args.source} {args.output}"
            )
        print(f"{args.output} is up to date")
        return
    output.write_text(rendered)


if __name__ == "__main__":
    main()
